def transform_complete_fixed(grid):
    """
    Fixed rule: Horizontal fills INCLUDE the target column if it has matching value.
    """
    h, w = len(grid), len(grid[0])
    result = [[0]*w for _ in range(h)]

    # Step 1: Find vertical sources
    vertical_sources = {}
    for c in range(w):
        for r in range(h):
            if grid[r][c] != 0:
                if r == 0:
                    vertical_sources[c] = grid[r][c]
                break

    # Step 2: Apply vertical fills
    for c, val in vertical_sources.items():
        for rr in range(1, h):
            if grid[rr][c] != 0:
                break
            row_has_val = any(grid[rr][cc] != 0 and grid[rr][cc] == val for cc in range(w))
            if row_has_val:
                break
            result[rr][c] = val
        result[0][c] = val

    # Step 3: Apply horizontal fills (including target column)
    for r in range(h):
        if r == 0:
            continue

        for c in range(w):
            if grid[r][c] != 0:
                val = grid[r][c]

                # Find nearest vertical columns
                nearest_left = None
                nearest_right = None

                for cc in range(c - 1, -1, -1):
                    if cc in vertical_sources and vertical_sources[cc] == val:
                        nearest_left = cc
                        break

                for cc in range(c + 1, w):
                    if cc in vertical_sources and vertical_sources[cc] == val:
                        nearest_right = cc
                        break

                # Fill left (including nearest_left)
                if nearest_left is not None:
                    for cf in range(c - 1, nearest_left - 1, -1):  # Inclusive of nearest_left
                        result[r][cf] = val

                # Fill right (including nearest_right)
                if nearest_right is not None:
                    for cf in range(c + 1, nearest_right + 1):  # Inclusive of nearest_right
                        result[r][cf] = val

    return result

