def transform_final(grid):
    """
    Final rule:
    1. For each column with topmost non-zero at row 0, fill vertically DOWN through
       empty cells, stopping when:
       - Hitting a cell with a non-zero value in the INPUT, OR
       - Hitting a row that contains a non-zero input cell with the SAME value as the vertical.

    2. For each cell NOT at row 0 with a value, fill horizontally toward the nearest
       vertical column with the SAME value (the target stays filled with the vertical's value).

    3. Keep all original non-zero cells from the input.
    """
    h, w = len(grid), len(grid[0])
    result = [[0]*w for _ in range(h)]

    # Step 1: Copy original grid into result
    for r in range(h):
        for c in range(w):
            result[r][c] = grid[r][c]

    # Step 2: Collect vertical fill information
    # vertical_source[c] = value, only if topmost non-zero in col c is at row 0
    vertical_source = {}
    for c in range(w):
        for r in range(h):
            if grid[r][c] != 0:
                if r == 0:
                    vertical_source[c] = grid[r][c]
                break

    # Step 3: Apply vertical fills (from original grid)
    for c, val in vertical_source.items():
        for rr in range(1, h):
            # Check if we should stop
            if grid[rr][c] != 0:  # Hit non-zero in input
                break
            # Check if this row has a non-zero with the same value
            row_has_same_val = any(
                grid[rr][cc] != 0 and grid[rr][cc] == val for cc in range(w)
            )
            if row_has_same_val:
                break
            # Fill if empty
            if result[rr][c] == 0:
                result[rr][c] = val

    # Step 4: Apply horizontal fills
    # For each non-zero cell NOT at row 0:
    for r in range(1, h):  # Skip row 0
        for c in range(w):
            original_val = grid[r][c]
            if original_val == 0:
                continue

            # Find nearest matching vertical (target column)
            target_left = None
            target_right = None

            for cc in range(c - 1, -1, -1):
                if cc in vertical_source and vertical_source[cc] == original_val:
                    target_left = cc
                    break

            for cc in range(c + 1, w):
                if cc in vertical_source and vertical_source[cc] == original_val:
                    target_right = cc
                    break

            # Fill toward targets through EMPTY cells in the RESULT
            # (cells already filled by verticals from the original grid stay)
            if target_left is not None:
                for cf in range(c - 1, target_left - 1, -1):
                    if result[r][cf] == 0:  # Only fill empty cells
                        result[r][cf] = original_val

            if target_right is not None:
                for cf in range(c + 1, target_right + 1):
                    if result[r][cf] == 0:
                        result[r][cf] = original_val

    return result

